        char buf[10000];
        memset(buf, 0, sizeof(buf));

        struct json_value *val = json_parse(*test_case, strlen(*test_case));
        if (!val) {
            printf("Failed to parse JSON: %s.\n", *test_case);
            return -1;
        }

        ret = json_serialize(val, buf, sizeof(buf));
        if (ret) {
            printf("Failed to serialize JSON: %s.\n", *test_case);
            return -1;
        }

        ret = strncmp(*test_case, buf, sizeof(buf));
        if (ret) {
            printf("No match: %s vs %s.\n", *test_case, buf);
            return -1;
        }

        json_free(val);

